1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useParams } from 'react-router-dom';
3	import {
4	  login, getGarcomToken, setGarcomToken, clearGarcomToken, getMe,
5	  getMesas, getProdutos, getMinhasComandas, getComanda, getItensProntos,
6	  abrirComanda, adicionarItens, editarItem, removerItem, enviarItens, fecharComanda,
7	  registrarPagamento,
8	} from '../../services/garcomService';
9	import { printTicketSetor } from '../../utils/printComanda';
10	import { getAcompanharUrls } from '../../utils/mesaAcompanharUrl';
11	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
12	import Icon from '../../components/AppIcon';
13	
14	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
15	const PAGAMENTO_LABEL = { pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito', cash: 'Dinheiro' };
16	
17	const MESA_STATUS_COR = {
18	  livre: 'bg-emerald-100 text-emerald-700 border-emerald-200',
19	  ocupada: 'bg-orange-100 text-orange-700 border-orange-200',
20	  aguardando_pagamento: 'bg-blue-100 text-blue-700 border-blue-200',
21	  bloqueada: 'bg-zinc-200 text-zinc-500 border-zinc-300',
22	};
23	const MESA_STATUS_LABEL = { livre: 'Livre', ocupada: 'Ocupada', aguardando_pagamento: 'Aguard. pagamento', bloqueada: 'Bloqueada' };
24	
25	const GarcomLogin = ({ loginKey, onLogin }) => {
26	  const [password, setPassword] = useState('');
27	  const [erro, setErro] = useState(null);
28	  const [loading, setLoading] = useState(false);
29	
30	  const handleSubmit = async (e) => {
31	    e.preventDefault();
32	    setErro(null);
33	    setLoading(true);
34	    try {
35	      const { token } = await login(loginKey, password);
36	      setGarcomToken(token);
37	      onLogin();
38	    } catch (err) {
39	      setErro(err.message ?? 'Senha inválida.');
40	    } finally {
41	      setLoading(false);
42	    }
43	  };
44	
45	  return (
46	    <div className="min-h-screen bg-[#F4F4F5] flex items-center justify-center p-4">
47	      <div className="bg-white rounded-2xl border border-[#E4E4E7] p-6 w-full max-w-sm shadow-lg">
48	        <div className="text-center mb-6">
49	          <div className="w-14 h-14 bg-[#FF441F]/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
50	            <Icon name="UtensilsCrossed" size={28} className="text-[#FF441F]" />
51	          </div>
52	          <h1 className="text-lg font-black text-[#18181B]">Portal do Garçom</h1>
53	          <p className="text-sm text-[#71717A] mt-1">Digite sua senha pra entrar</p>
54	        </div>
55	        <form onSubmit={handleSubmit} className="space-y-3">
56	          <input
57	            type="password"
58	            value={password}
59	            onChange={(e) => setPassword(e.target.value)}
60	            placeholder="Senha"
61	            autoFocus
62	            required
63	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-3 text-sm focus:outline-none focus:border-[#FF441F]"
64	          />
65	          {erro && <p className="text-xs text-red-600">{erro}</p>}
66	          <button type="submit" disabled={loading}
67	            className="w-full py-3 bg-[#FF441F] text-white font-bold rounded-xl hover:bg-[#E63A19] disabled:opacity-50 text-sm">
68	            {loading ? 'Entrando...' : 'Entrar'}
69	          </button>
70	        </form>
71	      </div>
72	    </div>
73	  );
74	};
75	
76	const AbrirComandaModal = ({ mesa, onFechar, onAberta }) => {
77	  const [nome, setNome] = useState('');
78	  const [telefone, setTelefone] = useState('');
79	  const [erro, setErro] = useState(null);
80	  const [salvando, setSalvando] = useState(false);
81	
82	  const submit = async (e) => {
83	    e.preventDefault();
84	    setErro(null);
85	    setSalvando(true);
86	    try {
87	      const comanda = await abrirComanda({ mesa_id: mesa?.id ?? null, cliente_nome: nome.trim(), cliente_telefone: telefone.trim() });
88	      onAberta(comanda);
89	    } catch (err) {
90	      setErro(err.message ?? 'Não foi possível abrir a comanda.');
91	    } finally {
92	      setSalvando(false);
93	    }
94	  };
95	
96	  return (
97	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
98	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
99	        <h2 className="text-base font-bold text-[#18181B] mb-1">
100	          {mesa ? `Abrir Mesa ${mesa.numero}` : 'Abrir comanda avulsa'}
101	        </h2>
102	        <p className="text-xs text-[#71717A] mb-4">Nome e telefone do cliente são obrigatórios antes de vender.</p>
103	        <form onSubmit={submit} className="space-y-3">
104	          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do cliente" required
105	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
106	          <input value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="Telefone do cliente" required
107	            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
108	          {erro && <p className="text-xs text-red-600">{erro}</p>}
109	          <div className="flex gap-2 pt-1">
110	            <button type="button" onClick={onFechar}
111	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
112	              Cancelar
113	            </button>
114	            <button type="submit" disabled={salvando}
115	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
116	              {salvando ? 'Abrindo...' : 'Abrir'}
117	            </button>
118	          </div>
119	        </form>
120	      </div>
121	    </div>
122	  );
123	};
124	
125	const FecharComandaModal = ({ comanda, onFechar, onFechada }) => {
126	  const [forma, setForma] = useState('pix');
127	  const [erro, setErro] = useState(null);
128	  const [salvando, setSalvando] = useState(false);
129	
130	  const confirmar = async () => {
131	    setErro(null);
132	    setSalvando(true);
133	    try {
134	      await fecharComanda(comanda.id, forma);
135	      onFechada();
136	    } catch (err) {
137	      setErro(err.message ?? 'Não foi possível fechar a comanda.');
138	    } finally {
139	      setSalvando(false);
140	    }
141	  };
142	
143	  return (
144	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
145	      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
146	        <h2 className="text-base font-bold text-[#18181B] mb-1">Fechar comanda</h2>
147	        <p className="text-xs text-[#71717A] mb-4">
148	          A mesa fica bloqueada aguardando pagamento — quem finaliza e emite o recibo é o caixa.
149	        </p>
150	        <label className="text-xs text-[#71717A]">Forma de pagamento informada pelo cliente</label>
151	        <select value={forma} onChange={(e) => setForma(e.target.value)}
152	          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2.5 text-sm mt-1 mb-3">
153	          <option value="pix">PIX</option>
154	          <option value="credit_card">Cartão de crédito</option>
155	          <option value="debit_card">Cartão de débito</option>
156	          <option value="cash">Dinheiro</option>
157	        </select>
158	        {erro && <p className="text-xs text-red-600 mb-2">{erro}</p>}
159	        <div className="flex gap-2">
160	          <button onClick={onFechar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A] hover:bg-[#F4F4F5]">
161	            Voltar
162	          </button>
163	          <button onClick={confirmar} disabled={salvando}
164	            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
165	            {salvando ? 'Fechando...' : 'Fechar comanda'}
166	          </button>
167	        </div>
168	      </div>
169	    </div>
170	  );
171	};
172	
173	const QuickAddModal = ({ produto, onFechar, onConfirmar }) => {
174	  const [quantidade, setQuantidade] = useState(1);
175	  const [observacao, setObservacao] = useState('');
176	  const [salvando, setSalvando] = useState(false);
177	
178	  const confirmar = async () => {
179	    setSalvando(true);
180	    try {
181	      await onConfirmar({ product_id: produto.id, quantity: quantidade, observacao: observacao.trim() || undefined });
182	    } finally {
183	      setSalvando(false);
184	    }
185	  };
186	
187	  return (
188	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-[60] p-4">
189	      <div className="bg-white rounded-2xl w-full max-w-sm p-5 shadow-2xl">
190	        <div className="flex items-center gap-3 mb-4">
191	          <div className="w-14 h-14 rounded-xl overflow-hidden bg-[#F4F4F5] flex-shrink-0">
192	            {produto.image_url
193	              ? <img src={produto.image_url} alt="" className="w-full h-full object-cover" />
194	              : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={20} className="text-[#A1A1AA]" /></div>}
195	          </div>
196	          <div className="min-w-0">
197	            <p className="text-sm font-bold text-[#18181B] truncate">{produto.name}</p>
198	            <p className="text-xs text-[#71717A]">{fmt(produto.price)}</p>
199	          </div>
200	        </div>
201	
202	        <label className="text-xs text-[#71717A]">Quantidade</label>
203	        <div className="flex items-center gap-3 mt-1 mb-3">
204	          <button onClick={() => setQuantidade((q) => Math.max(1, q - 1))}
205	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">−</button>
206	          <span className="text-lg font-bold text-[#18181B] w-8 text-center">{quantidade}</span>
207	          <button onClick={() => setQuantidade((q) => q + 1)}
208	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">+</button>
209	        </div>
210	
211	        <label className="text-xs text-[#71717A]">Observação (opcional)</label>
212	        <textarea value={observacao} onChange={(e) => setObservacao(e.target.value)} rows={2}
213	          placeholder="Ex: sem cebola, ponto da carne..."
214	          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm mt-1 mb-4 resize-none" />
215	
216	        <div className="flex gap-2">
217	          <button onClick={onFechar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A]">
218	            Cancelar
219	          </button>
220	          <button onClick={confirmar} disabled={salvando}
221	            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
222	            {salvando ? 'Adicionando...' : 'Adicionar'}
223	          </button>
224	        </div>
225	      </div>
226	    </div>
227	  );
228	};
229	
230	const ProdutoPickerModal = ({ produtos, onFechar, onAdicionado }) => {
231	  const [busca, setBusca] = useState('');
232	  const [categoria, setCategoria] = useState('todas');
233	  const [produtoAtivo, setProdutoAtivo] = useState(null);
234	
235	  const categorias = ['todas', ...new Set(produtos.map((p) => p.category_name ?? 'Outros'))];
236	  const filtrados = produtos.filter((p) => {
237	    const bateBusca = p.name.toLowerCase().includes(busca.toLowerCase());
238	    const bateCategoria = categoria === 'todas' || (p.category_name ?? 'Outros') === categoria;
239	    return bateBusca && bateCategoria;
240	  });
241	
242	  return (
243	    <div className="fixed inset-0 bg-white z-50 flex flex-col">
244	      <div className="p-4 border-b border-[#E4E4E7] sticky top-0 bg-white max-w-2xl w-full mx-auto">
245	        <div className="flex items-center gap-2 mb-3">
246	          <button onClick={onFechar} className="p-1 text-[#71717A]"><Icon name="ArrowLeft" size={20} /></button>
247	          <h2 className="text-base font-bold text-[#18181B]">Adicionar produto</h2>
248	        </div>
249	        <div className="relative">
250	          <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" />
251	          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto..." autoFocus
252	            className="w-full border border-[#E4E4E7] rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
253	        </div>
254	        <div className="flex gap-1.5 mt-3 overflow-x-auto pb-1">
255	          {categorias.map((c) => (
256	            <button key={c} onClick={() => setCategoria(c)}
257	              className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap flex-shrink-0 ${
258	                categoria === c ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] text-[#71717A]'
259	              }`}>
260	              {c === 'todas' ? 'Todas' : c}
261	            </button>
262	          ))}
263	        </div>
264	      </div>
265	
266	      <div className="flex-1 overflow-y-auto p-4 max-w-2xl w-full mx-auto space-y-2">
267	        {filtrados.map((p) => (
268	          <button key={p.id} onClick={() => setProdutoAtivo(p)}
269	            className="w-full bg-white border border-[#E4E4E7] rounded-xl p-2.5 flex items-center gap-3 text-left active:scale-[0.98] transition-transform">
270	            <div className="w-12 h-12 rounded-lg overflow-hidden bg-[#F4F4F5] flex-shrink-0">
271	              {p.image_url
272	                ? <img src={p.image_url} alt="" className="w-full h-full object-cover" />
273	                : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={18} className="text-[#A1A1AA]" /></div>}
274	            </div>
275	            <div className="min-w-0 flex-1">
276	              <p className="text-sm font-semibold text-[#18181B] truncate">{p.name}</p>
277	              <p className="text-xs text-[#71717A]">{fmt(p.price)}</p>
278	            </div>
279	            <Icon name="Plus" size={18} className="text-[#FF441F] flex-shrink-0" />
280	          </button>
281	        ))}
282	        {filtrados.length === 0 && <p className="text-sm text-[#A1A1AA] text-center py-6">Nenhum produto encontrado.</p>}
283	      </div>
284	
285	      {produtoAtivo && (
286	        <QuickAddModal
287	          produto={produtoAtivo}
288	          onFechar={() => setProdutoAtivo(null)}
289	          onConfirmar={async (item) => { await onAdicionado(item); setProdutoAtivo(null); }}
290	        />
291	      )}
292	    </div>
293	  );
294	};
295	
296	const PagamentoParcial = ({ comanda, onRegistrado, podePagamentoParcial }) => {
297	  const [valor, setValor] = useState('');
298	  const [forma, setForma] = useState('pix');
299	  const [valorRecebido, setValorRecebido] = useState('');
300	  const [erro, setErro] = useState(null);
301	  const [salvando, setSalvando] = useState(false);
302	
303	  const saldo = comanda.saldo?.saldo ?? 0;
304	  const troco = forma === 'cash' && valorRecebido ? Number(valorRecebido) - Number(valor || 0) : null;
305	
306	  const registrar = async () => {
307	    const v = Number(valor);
308	    if (!v || v <= 0) return;
309	    if (forma === 'cash' && valorRecebido && Number(valorRecebido) < v) {
310	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
311	      return;
312	    }
313	    setErro(null);
314	    setSalvando(true);
315	    try {
316	      await registrarPagamento(comanda.id, v, forma, forma === 'cash' && valorRecebido ? Number(valorRecebido) : undefined);
317	      setValor('');
318	      setValorRecebido('');
319	      await onRegistrado();
320	    } catch (err) {
321	      setErro(err.message ?? 'Não foi possível registrar o pagamento.');
322	    } finally {
323	      setSalvando(false);
324	    }
325	  };
326	
327	  return (
328	    <div className="bg-white rounded-xl border border-[#E4E4E7] p-3 space-y-2">
329	      <div className="flex justify-between text-sm">
330	        <span className="text-[#71717A]">Saldo devedor</span>
331	        <strong className={saldo > 0.01 ? 'text-[#FF441F]' : 'text-emerald-600'}>{fmt(saldo)}</strong>
332	      </div>
333	      {(comanda.pagamentos ?? []).length > 0 && (
334	        <div className="space-y-0.5">
335	          {comanda.pagamentos.map((p) => (
336	            <p key={p.id} className="text-xs text-[#71717A] flex justify-between">
337	              <span>{PAGAMENTO_LABEL[p.forma_pagamento] ?? p.forma_pagamento} ({p.origem === 'garcom' ? 'garçom' : 'caixa'})</span>
338	              <span>{fmt(p.valor)}</span>
339	            </p>
340	          ))}
341	        </div>
342	      )}
343	      {saldo > 0.01 && podePagamentoParcial && (
344	        <div className="space-y-1.5 pt-1">
345	          <div className="flex items-center gap-1.5">
346	            <input type="number" value={valor} onChange={(e) => setValor(e.target.value)} placeholder="Valor"
347	              className="w-20 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
348	            <select value={forma} onChange={(e) => setForma(e.target.value)}
349	              className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs">
350	              <option value="pix">PIX</option>
351	              <option value="credit_card">Cartão de crédito</option>
352	              <option value="debit_card">Cartão de débito</option>
353	              <option value="cash">Dinheiro</option>
354	            </select>
355	            <button onClick={registrar} disabled={salvando || !valor}
356	              className="px-2.5 py-1.5 bg-zinc-800 text-white rounded-lg text-xs font-bold disabled:opacity-40 flex-shrink-0">
357	              Pagar
358	            </button>
359	          </div>
360	          {forma === 'cash' && (
361	            <div className="flex items-center gap-1.5">
362	              <input type="number" value={valorRecebido} onChange={(e) => setValorRecebido(e.target.value)}
363	                placeholder="Valor recebido do cliente"
364	                className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
365	              {troco !== null && (
366	                <span className={`text-xs font-bold flex-shrink-0 ${troco < 0 ? 'text-red-600' : 'text-emerald-700'}`}>
367	                  Troco: {fmt(Math.max(troco, 0))}
368	                </span>
369	              )}
370	            </div>
371	          )}
372	        </div>
373	      )}
374	      {saldo > 0.01 && !podePagamentoParcial && (
375	        <p className="text-xs text-[#A1A1AA] pt-1">Você não tem permissão para registrar pagamento parcial.</p>
376	      )}
377	      {erro && <p className="text-xs text-red-600">{erro}</p>}
378	    </div>
379	  );
380	};
381	
382	const ComandaDetalhe = ({ comandaId, onVoltar, podePagamentoParcial }) => {
383	  const [comanda, setComanda] = useState(null);
384	  const [produtos, setProdutos] = useState([]);
385	  const [mostrarPicker, setMostrarPicker] = useState(false);
386	  const [enviando, setEnviando] = useState(false);
387	  const [mostrarFechar, setMostrarFechar] = useState(false);
388	  const [erro, setErro] = useState(null);
389	  const [mostrarQr, setMostrarQr] = useState(false);
390	  const [qrModo, setQrModo] = useState('online'); // 'online' | 'local'
391	
392	  const carregar = useCallback(async () => {
393	    const [c, p] = await Promise.all([getComanda(comandaId), getProdutos()]);
394	    setComanda(c);
395	    setProdutos(p);
396	  }, [comandaId]);
397	
398	  useEffect(() => { carregar(); }, [carregar]);
399	
400	  const adicionarProduto = async (item) => {
401	    setErro(null);
402	    try {
403	      await adicionarItens(comandaId, [item]);
404	      await carregar();
405	    } catch (err) {
406	      setErro(err.message ?? 'Não foi possível adicionar o item.');
407	    }
408	  };
409	
410	  const alterarQuantidade = async (item, delta) => {
411	    const novaQtd = item.quantity + delta;
412	    if (novaQtd < 1) return;
413	    setErro(null);
414	    try {
415	      await editarItem(comandaId, item.id, { quantity: novaQtd });
416	      await carregar();
417	    } catch (err) {
418	      setErro(err.message ?? 'Não foi possível alterar a quantidade.');
419	    }
420	  };
