8	
9	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
10	
11	/* ── Skeleton ────────────────────────────────────────────────────── */
12	const SkeletonProduto = () => (
13	  <div className="flex gap-4 p-4 bg-white rounded-2xl border border-[#E4E4E7] animate-pulse">
14	    <div className="flex-1 space-y-2">
15	      <div className="h-4 bg-[#E4E4E7] rounded-lg w-3/4" />
16	      <div className="h-3 bg-[#F4F4F5] rounded-lg w-full" />
17	      <div className="h-3 bg-[#F4F4F5] rounded-lg w-2/3" />
18	      <div className="h-7 bg-[#E4E4E7] rounded-xl w-24 mt-3" />
19	    </div>
