24	/* ── Card produto ────────────────────────────────────────────────── */
25	const ProdutoCard = ({ produto, onAdicionar, qtd, restauranteFechado }) => {
26	  const temPromo = produto.tags?.includes('promo') && produto.preco_promo != null;
27	  const indisponivel = produto.disponivel === false || restauranteFechado;
28	  const precoFinal = temPromo ? produto.preco_promo : produto.price;
29	
30	  return (
31	    <motion.div
32	      layout
33	      whileHover={indisponivel ? {} : { y: -1 }}
34	      className={`flex gap-4 p-4 bg-white rounded-2xl border transition-all h-full ${
35	        indisponivel ? 'border-[#E4E4E7] opacity-60' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/20'
36	      }`}
37	    >
38	      <div className="flex-1 flex flex-col justify-between min-w-0">
39	        <div>
40	          <div className="flex items-start gap-2 flex-wrap">
41	            <p className="font-semibold text-[#18181B] text-sm leading-snug flex-1">{produto.name}</p>
42	            {produto.destaque && (
43	              <span className="text-[10px] px-1.5 py-0.5 bg-yellow-400/20 text-yellow-700 rounded font-bold flex-shrink-0">⭐ Destaque</span>
44	            )}
45	            {produto.tags?.includes('mais_vendido') && (
46	              <span className="text-[10px] px-1.5 py-0.5 bg-amber-100 text-amber-700 rounded font-bold flex-shrink-0">🔥 Top</span>
47	            )}
48	          </div>
49	          {produto.description && (
50	            <p className="text-xs text-[#71717A] mt-1 line-clamp-2">{produto.description}</p>
51	          )}
52	        </div>
53	
54	        <div className="flex items-center justify-between mt-3 gap-2 flex-wrap">
55	          <div>
56	            {temPromo && <p className="text-xs line-through text-[#71717A]">{fmt(produto.price)}</p>}
57	            <div className="flex items-center gap-1.5">
58	              <p className={`text-base font-bold ${temPromo ? 'text-green-600' : 'text-[#FF441F]'}`}>{fmt(precoFinal)}</p>
59	              {temPromo && <span className="text-[10px] bg-green-100 text-green-700 px-1.5 py-0.5 rounded font-bold">PROMO</span>}
60	            </div>
61	          </div>
62	
63	          {!indisponivel ? (
64	            <div className="flex items-center gap-2 flex-shrink-0">
65	              {qtd === 0 ? (
66	                <motion.button whileTap={{ scale: 0.92 }} onClick={() => onAdicionar(produto, precoFinal)}
67	                  className="px-3.5 py-1.5 bg-[#FF441F] text-white text-xs font-bold rounded-xl hover:bg-[#E63A19] transition-colors">
68	                  Adicionar
69	                </motion.button>
70	              ) : (
71	                <div className="flex items-center gap-2">
72	                  <button onClick={() => onAdicionar(produto, precoFinal, -1)}
73	                    className="w-7 h-7 bg-[#F4F4F5] rounded-full font-bold text-[#27272A] flex items-center justify-center hover:bg-[#E4E4E7] text-base">−</button>
74	                  <span className="text-sm font-bold text-[#18181B] w-5 text-center">{qtd}</span>
75	                  <button onClick={() => onAdicionar(produto, precoFinal, +1)}
76	                    className="w-7 h-7 bg-[#FF441F] rounded-full font-bold text-white flex items-center justify-center hover:bg-[#E63A19] text-base">+</button>
77	                </div>
78	              )}
79	            </div>
80	          ) : (
81	            <span className="text-xs text-[#71717A] bg-[#F4F4F5] px-2 py-1 rounded-lg">Indisponível</span>
82	          )}
83	        </div>
84	      </div>
85	
86	      {produto.image_url && (
87	        <div className="relative flex-shrink-0 w-28 h-24">
88	          <img src={produto.image_url} alt={produto.name} className="w-full h-full object-cover rounded-xl" />
89	          {indisponivel && (
90	            <div className="absolute inset-0 bg-white/60 rounded-xl flex items-center justify-center">
91	              <span className="text-[10px] text-[#71717A] font-semibold">Indisponível</span>
92	            </div>
93	          )}
94	        </div>
95	      )}
96	    </motion.div>
97	  );
98	};
99	
100	/* ── Conteúdo do carrinho (mobile + desktop) ─────────────────────── */
101	const CarrinhoConteudo = ({ carrinho, onAdicionar, onFechar, onCheckout }) => {
102	  const totalItens = carrinho.reduce((acc, i) => acc + i.qtd, 0);
103	  const totalValor = carrinho.reduce((acc, i) => acc + i.price * i.qtd, 0);
104	
105	  return (
106	    <>
107	      <div className="flex items-center justify-between px-5 pt-4 pb-3 border-b border-[#E4E4E7] flex-shrink-0">
108	        <h3 className="font-bold text-[#18181B] text-base">
109	          Carrinho <span className="text-[#FF441F]">({totalItens})</span>
110	        </h3>
111	        {onFechar && (
112	          <button onClick={onFechar} className="p-1.5 hover:bg-[#F4F4F5] rounded-lg">
113	            <Icon name="X" size={18} className="text-[#71717A]" />
114	          </button>
115	        )}
116	      </div>
117	
118	      <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3">
119	        <AnimatePresence>
120	          {carrinho.map((item) => (
121	            <motion.div key={item.id} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 16 }}
122	              className="flex items-center gap-3">
123	              {item.image_url && (
124	                <img src={item.image_url} alt={item.name} className="w-12 h-12 rounded-xl object-cover flex-shrink-0" />
125	              )}
126	              <div className="flex-1 min-w-0">
127	                <p className="text-sm font-medium text-[#18181B] truncate">{item.name}</p>
128	                <p className="text-xs text-[#71717A]">{fmt(item.price)}</p>
129	              </div>
130	              <div className="flex items-center gap-1.5 flex-shrink-0">
131	                <button onClick={() => onAdicionar(item, item.price, -1)}
132	                  className="w-6 h-6 bg-[#F4F4F5] rounded-full text-sm font-bold text-[#27272A] flex items-center justify-center">−</button>
133	                <span className="text-sm font-bold text-[#18181B] w-4 text-center">{item.qtd}</span>
134	                <button onClick={() => onAdicionar(item, item.price, +1)}
135	                  className="w-6 h-6 bg-[#FF441F] rounded-full text-sm font-bold text-white flex items-center justify-center">+</button>
136	              </div>
137	            </motion.div>
138	          ))}
139	        </AnimatePresence>
140	      </div>
141	
142	      <div className="px-5 py-4 border-t border-[#E4E4E7] flex-shrink-0">
143	        <div className="flex justify-between text-sm mb-1">
144	          <span className="text-[#71717A]">Subtotal</span>
145	          <span className="font-medium text-[#27272A]">{fmt(totalValor)}</span>
146	        </div>
147	        <div className="flex justify-between text-base font-bold mb-4">
148	          <span className="text-[#18181B]">Total</span>
149	          <span className="text-[#FF441F]">{fmt(totalValor)}</span>
150	        </div>
151	        <motion.button whileTap={{ scale: 0.98 }} onClick={onCheckout}
152	          className="w-full py-3.5 bg-[#FF441F] text-white font-bold rounded-2xl hover:bg-[#E63A19] transition-colors text-sm shadow-lg shadow-[#FF441F]/20">
153	          Finalizar pedido →
154	        </motion.button>
155	      </div>
156	    </>
157	  );
158	};
159	
160	/* ── Drawer mobile (bottom sheet) ────────────────────────────────── */
161	const CarrinhoMobile = ({ carrinho, onAdicionar, onFechar, onCheckout }) => (
162	  <>
163	    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
164	      onClick={onFechar} className="fixed inset-0 bg-black/40 z-40 lg:hidden" />
165	    <motion.div
166	      initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
167	      transition={{ type: 'spring', damping: 28, stiffness: 300 }}
168	      className="fixed bottom-0 left-0 right-0 z-50 bg-white rounded-t-3xl shadow-2xl lg:hidden max-h-[82vh] flex flex-col"
169	    >
170	      <div className="w-10 h-1 bg-[#E4E4E7] rounded-full mx-auto mt-3 mb-1 flex-shrink-0" />
171	      <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={onFechar} onCheckout={onCheckout} />
172	    </motion.div>
173	  </>
174	);
175	
176	/* ── Sidebar desktop ─────────────────────────────────────────────── */
177	const CarrinhoDesktop = ({ carrinho, onAdicionar, onCheckout }) => (
178	  <aside className="hidden lg:block w-80 xl:w-96 flex-shrink-0">
179	    <div className="sticky top-28 bg-white rounded-2xl border border-[#E4E4E7] shadow-sm overflow-hidden flex flex-col max-h-[calc(100vh-120px)]">
180	      {carrinho.length === 0 ? (
181	        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
182	          <Icon name="ShoppingCart" size={44} className="text-[#E4E4E7] mb-3" />
183	          <p className="text-sm font-semibold text-[#27272A]">Carrinho vazio</p>
184	          <p className="text-xs text-[#71717A] mt-1">Adicione itens do cardápio</p>
185	        </div>
186	      ) : (
187	        <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={null} onCheckout={onCheckout} />
188	      )}
189	    </div>
190	  </aside>
191	);
192	
193	/* ── Componente principal ────────────────────────────────────────── */
194	const RestauranteCatalogo = ({ dadosPreCarregados } = {}) => {
195	  const { slug: slugParam } = useParams();
196	  const navigate = useNavigate();
197	  const { isAuthenticated, isRestaurantOwner, isAdmin } = useAuth();
198	  const [data, setData] = useState(dadosPreCarregados ?? null);
199	  const [loading, setLoading] = useState(!dadosPreCarregados);
200	  const [erro, setErro] = useState(null);
201	  const [carrinho, setCarrinho] = useState([]);
202	  const [catAtiva, setCatAtiva] = useState('todos');
203	  const [carrinhoAberto, setCarrinhoAberto] = useState(false);
204	
205	  // Quando aberto via domínio customizado (dadosPreCarregados vindo do HomeRouter),
206	  // não existe :slug na URL — o fetch abaixo é pulado, os dados já chegam prontos.
207	  useEffect(() => {
208	    if (dadosPreCarregados) return;
209	    setLoading(true);
210	    getCardapioPorSlug(slugParam)
211	      .then((d) => {
212	        setData(d);
213	        setCatAtiva('todos');
214	      })
215	      .catch((e) => setErro(e.message))
216	      .finally(() => setLoading(false));
217	  }, [slugParam, dadosPreCarregados]);
218	
219	  // Slug efetivo pro checkout: vem da URL em /r/:slug, ou do próprio payload
220	  // quando a loja foi aberta pelo domínio customizado (sem slug na URL).
